function quotationTotals(items=quotationDraftItems,taxRate=Number($('#quotationTax')?.value||16)){const subtotal=items.reduce((sum,item)=>sum+(Number(item.quantity)||0)*(Number(item.unitPrice)||0),0),discountTotal=items.reduce((sum,item)=>sum+(Number(item.quantity)||0)*(Number(item.unitPrice)||0)*(Number(item.discount)||0)/100,0),taxable=subtotal-discountTotal,taxAmount=taxable*taxRate/100;return {subtotal,discountTotal,taxable,taxAmount,total:taxable+taxAmount}}
