function confirmCommercialOrderActivation(order){if(!order||order.status==='active')return;$('#clientAcceptanceOrderId').value=order.id;$('#clientAcceptanceTitle').textContent=`Activar ${order.id}`;$('#clientAcceptanceType').value='customer_po';$('#clientAcceptanceReference').value='';$('#clientAcceptanceFile').value='';$('#clientAcceptanceNotes').value='';$('#clientAcceptanceDialog').showModal()}
async function submitClientAcceptance(){
  const order=commercialOrders.find(item=>item.id===$('#clientAcceptanceOrderId').value);if(!order||order.status==='active')return;
  const type=$('#clientAcceptanceType').value,reference=$('#clientAcceptanceReference').value.trim(),file=$('#clientAcceptanceFile').files[0],notes=$('#clientAcceptanceNotes').value.trim();
  if(!reference&&!file){showToast('Registra una referencia o adjunta la evidencia de aceptación.');return}
  let fileHash='',documentId=null;
  if(file){if(file.size>8*1024*1024){showToast('La evidencia no debe superar 8 MB.');return}fileHash=await fileFingerprint(await file.arrayBuffer());documentId=`ACEPTACION-${order.id}`;try{await storeQuotationDocument(documentId,file)}catch{showToast('No fue posible conservar la evidencia. La orden no se activó.');return}}
  showActionConfirmation({kicker:'ACTIVAR PEDIDO DE VENTA',title:`¿Validar la aceptación de ${order.id}?`,text:'La confirmación habilitará la generación de necesidades y propuestas de compra. La cotización por sí sola no afecta inventario.',summaryTitle:'EVIDENCIA DEL CLIENTE',items:[{name:`${order.id} · ${order.client}`,detail:`${({customer_po:'OC del cliente',signed_quotation:'Cotización firmada',authorization_email:'Correo de autorización',deposit:'Anticipo / depósito'})[type]} · ${reference||file.name}`,value:money(order.total,order.currency),delta:1}],confirmLabel:'Registrar y activar',onConfirm:()=>{
    const activated=new Date(),actorName=window.BioAccess?.currentUser()?.name||'Usuario',acceptance={type,reference:reference||null,fileName:file?.name||null,fileSize:file?.size||0,fileHash,documentId,notes,acceptedAt:activated.toISOString(),acceptedBy:actorName};
    order.acceptance=acceptance;order.status='active';order.activatedAtISO=activated.toISOString();order.activatedAt=activated.toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'});order.activatedBy=actorName;order.timeline=[...(order.timeline||[]),{status:'accepted',label:'Aceptación del cliente registrada',at:order.activatedAtISO,by:actorName,evidence:{type,reference:reference||file?.name,fileHash}},{status:'active',label:'Pedido de venta Bio activado',at:order.activatedAtISO,by:actorName}];
    const quotation=quotations.find(item=>item.id===order.quotationId);if(quotation){quotation.status='accepted';quotation.acceptance={...acceptance};quotation.statusHistory=[...(quotation.statusHistory||[]),{status:'accepted',at:activated.toISOString(),by:actorName,reference:reference||file?.name||null}]}
    save();$('#clientAcceptanceDialog').close();window.dispatchEvent(new CustomEvent('bio:client-order-activated',{detail:{orderId:order.id}}));renderQuotationHistory($('#quotationHistorySearch').value);renderCommercialOrders($('#commercialOrderSearch').value);showToast(`Pedido ${order.id} activo con aceptación auditable.`)
  }})
}
function renderModuleSummaries(){
  const totalStock=products.reduce((sum,product)=>sum+Number(product.a1||0)+Number(product.a2||0),0);
  $('#warehouseSummaryProducts').textContent=products.length;
  $('#warehouseSummaryStock').textContent=`${totalStock.toLocaleString('es-MX')} uds.`;
  $('#warehouseSummaryMovements').textContent=movements.length;
  $('#warehouseSummaryLow').textContent=products.filter(product=>Number(product.a1||0)+Number(product.a2||0)<Number(product.min||0)).length;
  $('#productSummaryProducts').textContent=products.length;
  $('#productSummarySuppliers').textContent=suppliers.length;
  $('#productSummaryLoads').textContent=priceLoads.length;
  $('#productSummaryUnlinked').textContent=products.filter(product=>!product.supplierId).length;
}
