  const currentPurchaseSupplier=$('#purchaseSupplier')?.value||'';$('#purchaseSupplier').innerHTML=`<option value="">Selecciona un proveedor</option>${suppliers.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}`;$('#purchaseSupplier').value=currentPurchaseSupplier;
  const currentPriceSupplier=$('#priceSupplier')?.value||pendingPriceBatch?.supplierId||'';$('#priceSupplier').innerHTML=`<option value="">Selecciona un proveedor</option>${suppliers.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}`;$('#priceSupplier').value=currentPriceSupplier;$('#selectPriceFile').disabled=!currentPriceSupplier;
  $('#priceLoadHistory').innerHTML=priceLoads.length?priceLoads.map(load=>`<article class="price-audit-row"><span class="audit-file-icon"><i data-lucide="file-check-2"></i></span><div class="audit-main"><strong>${escapeHtml(load.fileName)}</strong><small>${escapeHtml(load.supplierName)} · ${load.id} · ${escapeHtml(load.appliedAt)}</small><span>${load.sheets.length} hoja${load.sheets.length===1?'':'s'} revisada${load.sheets.length===1?'':'s'} · ${load.currencies.join(', ')||'Moneda no identificada'} · ${load.present} vigentes · ${load.missing} no incluidos</span></div><div class="audit-integrity"><small>HUELLA DEL ARCHIVO</small><code>${escapeHtml((load.fileHash||'No disponible').slice(0,16))}${load.fileHash&&load.fileHash.length>16?'…':''}</code></div><button class="download-price-audit" data-price-load-id="${load.id}" title="Descargar comprobante de carga" aria-label="Descargar comprobante ${load.id}"><i data-lucide="download"></i></button></article>`).join(''):'<div class="price-audit-empty"><i data-lucide="shield-check"></i><span>Las cargas confirmadas aparecerán aquí con su comprobante de auditoría.</span></div>';
