const CODE39={"0":"111221211","1":"211211112","2":"112211112","3":"212211111","4":"111221112","5":"211221111","6":"112221111","7":"111211212","8":"211211211","9":"112211211","A":"211112112","B":"112112112","C":"212112111","D":"111122112","E":"211122111","F":"112122111","G":"111112212","H":"211112211","I":"112112211","J":"111122211","K":"211111122","L":"112111122","M":"212111121","N":"111121122","O":"211121121","P":"112121121","Q":"111111222","R":"211111221","S":"112111221","T":"111121221","U":"221111112","V":"122111112","W":"222111111","X":"121121112","Y":"221121111","Z":"122121111","-":"121111212",".":"221111211"," ":"122111211","*":"121121211","$":"121212111","/":"121211121","+":"121112121","%":"111212121"};
function drawCode39(doc,value,x,y,width,height){const text=`*${String(value||'SIN-CODIGO').toUpperCase().replace(/[^0-9A-Z.\- $/+%]/g,'-')}*`,patterns=[...text].map(char=>CODE39[char]||CODE39['-']),units=patterns.reduce((sum,pattern)=>sum+[...pattern].reduce((total,digit)=>total+Number(digit),0)+1,0),scale=width/units;let cursor=x;doc.setFillColor(18,25,38);patterns.forEach(pattern=>{[...pattern].forEach((digit,index)=>{const barWidth=Number(digit)*scale;if(index%2===0)doc.rect(cursor,y,barWidth,height,'F');cursor+=barWidth});cursor+=scale})}
function previewProductLabels(items){const PDF=window.jspdf?.jsPDF;if(!PDF||!items.length)return showToast('Selecciona al menos un producto para generar etiquetas.');const doc=new PDF({orientation:'portrait',unit:'mm',format:'a4'}),labelWidth=62,labelHeight=33,marginX=8,marginY=9,gapX=4,gapY=2,perPage=24;items.forEach((product,index)=>{if(index&&index%perPage===0)doc.addPage();const slot=index%perPage,col=slot%3,row=Math.floor(slot/3),x=marginX+col*(labelWidth+gapX),y=marginY+row*(labelHeight+gapY);doc.setDrawColor(206,213,225);doc.setFillColor(255,255,255);doc.roundedRect(x,y,labelWidth,labelHeight,2,2,'FD');doc.setFillColor(18,25,38);doc.roundedRect(x,y,labelWidth,7,2,2,'F');doc.rect(x,y+4,labelWidth,3,'F');doc.setFillColor(49,87,164);doc.roundedRect(x+3,y+1.5,4,4,1,1,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(6.2);doc.text('BIO · IDENTIFICACION DE PRODUCTO',x+9,y+4.4);doc.setTextColor(25,31,42);doc.setFontSize(7.2);doc.text(doc.splitTextToSize(String(product.name),labelWidth-7).slice(0,2),x+3.5,y+11);doc.setTextColor(94,105,122);doc.setFont('helvetica','normal');doc.setFontSize(5.5);doc.text(`Cat. ${product.number||'-'}  ·  SKU ${product.sku||'-'}`,x+3.5,y+18);drawCode39(doc,product.sku||product.number,x+3.5,y+20,labelWidth-7,7);doc.setTextColor(42,50,63);doc.setFont('courier','bold');doc.setFontSize(5.5);doc.text(String(product.sku||product.number||'SIN-CODIGO'),x+labelWidth/2,y+29.5,{align:'center'})});window.BioFlowDocs?.present(doc,{title:'ETIQUETAS DE PRODUCTO',folio:`${items.length} etiqueta${items.length===1?'':'s'}`,filename:`etiquetas-productos-${new Date().toISOString().slice(0,10)}.pdf`});return doc}
