function showActionConfirmation({kicker,title,text,summaryTitle,items,confirmLabel,cancelLabel='Cancelar',onConfirm,onCancel}){pendingConfirmedAction=onConfirm;pendingCancelledAction=onCancel;$('#actionConfirmKicker').textContent=kicker;$('#actionConfirmTitle').textContent=title;$('#actionConfirmText').textContent=text;$('#actionSummaryTitle').textContent=summaryTitle;$('#actionSummaryList').style.cssText='list-style:none;padding:0;margin:0;max-height:155px;overflow:auto';$('#actionSummaryList').innerHTML=items.map(item=>`<li style="min-height:49px;padding:10px 11px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #edf0ec;color:#6e796f;font:500 10px/1.45 Manrope,sans-serif"><span><strong style="color:#213026;font:700 11px Manrope,sans-serif">${item.name}</strong><br>${item.detail}</span><b style="font:500 10px 'DM Mono',monospace;color:${item.delta>0?'#208766':'#c96b4f'};white-space:nowrap">${item.value??`${item.delta>0?'+ ':''}${item.delta} uds.`}</b></li>`).join('');$('#confirmActionLabel').textContent=confirmLabel;$('#cancelAction').textContent=cancelLabel;setModalBackgroundBlur(true);$('#actionConfirmDialog').showModal();lucide.createIcons();}
