const normalizePriceToken=value=>String(value??'').replace(/\u00a0/g,' ').trim().toUpperCase();
const normalizeHeader=value=>normalizePriceToken(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]+/g,' ').trim();
const parsePriceNumber=value=>{if(typeof value==='number')return value;let clean=String(value??'').trim().replace(/[^0-9,.-]/g,'');if(!clean)return Number.NaN;if(clean.includes('.')&&clean.includes(','))clean=clean.replace(/,/g,'');else if(clean.includes(',')&&!clean.includes('.'))clean=clean.replace(',','.');return Number(clean)};
const supportedCurrencies=['USD','CAD','MXN','EUR'];
function detectCurrency(value){const raw=String(value??''),text=normalizeHeader(raw);if(/\bCAD\b|\bCDN\b|CANAD|DOLAR CAN/.test(text)||raw.includes('C$'))return 'CAD';if(/\bEUR\b|EURO/.test(text)||raw.includes('€'))return 'EUR';if(/\bMXN\b|PESO MEX|MEXICAN PESO|MONEDA NACIONAL/.test(text)||raw.includes('MX$'))return 'MXN';if(/\bUSD\b|DOLAR AMERIC|US DOLLAR/.test(text)||raw.includes('US$'))return 'USD';if(/\bDOLAR\b/.test(text))return 'USD';return ''}
async function fileFingerprint(buffer){if(!window.crypto?.subtle)return '';const digest=await crypto.subtle.digest('SHA-256',buffer);return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
