  pendingPriceBatch=null;$('#priceFile').value='';$('#pricePreviewBody').innerHTML='';$('#pricePreviewSummary').textContent=message;$('#priceReviewTools').hidden=true;$('#selectVisiblePrices').checked=false;$('#applyPrices').disabled=true;
