function confirmDeletePriceRows(targetRows){if(!targetRows.length)return;showActionConfirmation({kicker:'AJUSTAR CONCILIACIÓN',title:`¿Eliminar ${targetRows.length} resultado${targetRows.length===1?'':'s'}?`,text:'Estos renglones dejarán de contar como presentes. Si corresponden al proveedor, podrían quedar marcados como no incluidos al aplicar la lista.',summaryTitle:'RESULTADOS A ELIMINAR',items:targetRows.slice(0,10).map(row=>({name:`${row.code} · ${row.product?.name||row.description||'Sin coincidencia'}`,detail:`${row.sheetName} · fila ${row.sourceRow} · ${row.unit||'sin unidad'}`,delta:-1,value:'Eliminar'})),confirmLabel:'Eliminar de la revisión',onConfirm:()=>{const ids=new Set(targetRows.map(row=>row.reviewId));pendingPriceBatch.rows=pendingPriceBatch.rows.filter(row=>!ids.has(row.reviewId));pendingPriceBatch.deletedCount+=targetRows.length;populatePriceReviewFilters();renderPendingPriceReview();showToast(`${targetRows.length} resultado${targetRows.length===1?'':'s'} eliminado${targetRows.length===1?'':'s'} de la conciliación.`)}})}
