$('#applyPrices').addEventListener('click',()=>{
  if(!pendingPriceBatch)return;recalculatePriceBatch();
  const {supplierId,rows,missingProducts,fileName,fileHash,fileSize,sheets,relevantSheets,ignoredSheets,currencies,duplicates,sheetReports}=pendingPriceBatch;
  const presentRows=rows.filter(row=>row.matched),validRows=rows.filter(row=>row.valid&&!row.skipped),skippedRows=rows.filter(row=>row.skipped),unitUpdates=presentRows.filter(row=>!row.skipped&&row.unit&&row.product.unit!==row.unit),brandUpdates=presentRows.filter(row=>!row.skipped&&row.brand&&row.product.brand!==row.brand),supplierProducts=products.filter(p=>p.supplierId===supplierId),supplier=suppliers.find(s=>s.id===supplierId);
  const updates=validRows.filter(row=>Number(row.product.price)!==row.price||row.product.priceCurrency!==row.currency),returning=presentRows.filter(row=>row.product.priceListStatus==='missing'),newMissing=missingProducts.filter(product=>product.priceListStatus!=='missing');
  if(!supplierProducts.length){showToast('Este proveedor todavía no tiene productos relacionados.');return}
  const items=[
    ...updates.slice(0,6).map(row=>({name:`${row.product.number} · ${row.product.name}`,detail:`${row.sheetName} · Actual: ${money(row.product.price,row.product.priceCurrency)}`,delta:row.price-Number(row.product.price||0),value:money(row.price,row.currency)})),
    ...newMissing.slice(0,4).map(product=>({name:`${product.number} · ${product.name}`,detail:'No aparece en la lista que se aplicará',delta:-1,value:'Marcar no incluido'})),
    ...returning.slice(0,3).map(row=>({name:`${row.product.number} · ${row.product.name}`,detail:'Vuelve a aparecer en la lista',delta:1,value:'Restablecer vigente'})),
    ...unitUpdates.slice(0,3).map(row=>({name:`${row.product.number} · ${row.product.name}`,detail:`Unidad actual: ${row.product.unit||'sin dato'}`,delta:1,value:row.unit}))
  ];
  if(!items.length){const detail=presentRows.length?`Se renovará la vigencia de ${presentRows.length} producto${presentRows.length===1?'':'s'} sin cambiar precios inválidos.`:'Todos los productos del proveedor conservarán el indicador de no incluidos.';items.push({name:presentRows.length?'Conciliación sin cambios de precio':'Lista sin coincidencias',detail,delta:presentRows.length?1:-1,value:presentRows.length?`${presentRows.length} vigentes`:`${missingProducts.length} ausentes`})}
  showActionConfirmation({
    kicker:'VALIDAR LISTA DE PRECIOS',title:`¿Aplicar lista de ${supplier.name}?`,text:`Se revisaron ${sheets.length} hoja${sheets.length===1?'':'s'} y se detectaron ${currencies.join(', ')||'monedas sin identificar'}. Se aplicarán ${updates.length} precio${updates.length===1?'':'s'} y ${unitUpdates.length} unidad${unitUpdates.length===1?'':'es'}; ${skippedRows.length} resultado${skippedRows.length===1?'':'s'} se omitirá${skippedRows.length===1?'':'n'} y ${pendingPriceBatch.deletedCount} fue${pendingPriceBatch.deletedCount===1?'':'ron'} eliminado${pendingPriceBatch.deletedCount===1?'':'s'} de la revisión.`,summaryTitle:'RESUMEN DE LA CONCILIACIÓN',items,confirmLabel:'Confirmar y aplicar',
    onConfirm:()=>{
      const batch=`PRE-${Date.now().toString().slice(-6)}`,registeredAt=new Date().toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}),seenIds=new Set(presentRows.map(row=>row.product.id));
      supplierProducts.forEach(product=>{product.priceListStatus=seenIds.has(product.id)?'current':'missing';product.lastPriceBatch=batch;product.lastPriceListAt=registeredAt});
      unitUpdates.forEach(row=>row.product.unit=row.unit);brandUpdates.forEach(row=>row.product.brand=row.brand);
      updates.forEach(row=>{const before=Number(row.product.price||0),beforeCurrency=row.product.priceCurrency||'MXN';row.product.price=row.price;row.product.priceCurrency=row.currency;movements.unshift(newMovement({type:'precio',title:`Actualización de precio · ${batch}`,detail:`${supplier.name} · ${row.product.number} · ${row.product.name} · hoja ${row.sheetName} | ${money(before,beforeCurrency)} → ${money(row.price,row.currency)}`,qty:`${money(before,beforeCurrency)} → ${money(row.price,row.currency)}`,time:'Ahora'}))});
      supplier.lastPriceUploadAt=registeredAt;supplier.lastPriceBatch=batch;supplier.lastPriceFile=fileName;
      const auditMovement=newMovement({type:'precio',title:`Carga de lista de precios · ${batch}`,detail:`${supplier.name} · ${fileName} | ${sheets.length} hojas · ${currencies.join(', ')||'sin moneda'} · ${presentRows.length} vigentes · ${missingProducts.length} no incluidos · ${updates.length} precios · ${unitUpdates.length} unidades · ${skippedRows.length} omitidos · ${pendingPriceBatch.deletedCount} eliminados`,qty:`${presentRows.length} vigentes · ${missingProducts.length} ausentes`,time:'Ahora'});movements.unshift(auditMovement);
      priceLoads.unshift({id:batch,movementId:auditMovement.id,supplierId,supplierName:supplier.name,fileName,fileSize,fileHash,appliedAt:registeredAt,sheets,relevantSheets,ignoredSheets,currencies,duplicates,present:presentRows.length,missing:missingProducts.length,unmatched:rows.length-presentRows.length,updated:updates.length,unitsUpdated:unitUpdates.length,skipped:skippedRows.length,deleted:pendingPriceBatch.deletedCount,sheetReports});
      save();render();pendingPriceBatch=null;$('#pricePreviewBody').innerHTML='';$('#priceReviewTools').hidden=true;$('#pricePreviewSummary').textContent=`Lote ${batch} aplicado a ${supplier.name}. ${updates.length} precio${updates.length===1?'':'s'} y ${unitUpdates.length} unidad${unitUpdates.length===1?'':'es'} actualizados; ${skippedRows.length} resultado${skippedRows.length===1?'':'s'} omitido${skippedRows.length===1?'':'s'}.`;$('#applyPrices').disabled=true;$('#priceFile').value='';showToast(`Lista ${batch} aplicada únicamente a ${supplier.name}.`);
    }
  });
});
